    private static List<BlockPos> square(BlockPos source){return List.of(source,source.east(2),source.south(2),source.offset(2,0,2));}
    private static List<ItemStack> perpendicularWands(ServerPlayer player,BlockPos source){
        var a=wand(Vec3.atLowerCornerOf(source.east()),0);
        var b=wand(Vec3.atLowerCornerOf(source.south()),0);var plane=SymmetryWandItem.getMirror(b);plane.setOrientation(PlaneMirror.Align.XY.ordinal());SymmetryWandItem.configureSettings(b,plane);
        player.getInventory().setItem(7,a);player.getInventory().setItem(8,b);return List.of(a,b);
    }
    private static void original(ServerPlayer player,BlockPos target){var stock=player.getMainHandItem();var context=new BlockPlaceContext(player,InteractionHand.MAIN_HAND,stock,new BlockHitResult(Vec3.atCenterOf(target),Direction.UP,target,false));if(!((BlockItem)stock.getItem()).place(context).consumesAction())throw new AssertionError("Genuine original native BlockItem placement refused");}
    private static void footprint(GameTestHelper h,BlockPos source,Block block,boolean corner){for(var target:square(source))h.assertTrue(target.equals(source.offset(2,0,2))&&!corner?h.getLevel().getBlockState(target).isAir():h.getLevel().getBlockState(target).is(block),"Independent exact native footprint at "+target);}
    private static void owners(GameTestHelper h,ServerPlayer player,List<ItemStack> wands){for(int index=0;index<2;index++)h.assertTrue(player.getInventory().getItem(7+index)==wands.get(index)&&SymmetryWandItem.isEnabled(wands.get(index))&&!wands.get(index).getOrDefault(AllDataComponents.SYMMETRY_WAND_SIMULATE,false),"Exact actual hotbar wand owner remains enabled without suppression component mutation");}
    private static int loose(GameTestHelper h,BlockPos source,Item item){return h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(source).inflate(4)).stream().filter(entity->entity.getItem().is(item)).mapToInt(entity->entity.getItem().getCount()).sum();}

