    private static ItemStack configuredMaterial(Item item,int amount,String name){var stack=new ItemStack(item,amount);stack.set(DataComponents.CUSTOM_NAME,Component.literal(name));stack.set(DataComponents.MAX_STACK_SIZE,16);var data=new net.minecraft.nbt.CompoundTag();data.putString("OriginalConfiguration",name);stack.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));return stack;}
    private static int variantAmount(ServerPlayer player,ItemStack variant){int total=0;for(int slot=0;slot<player.getInventory().getContainerSize();slot++){var stack=player.getInventory().getItem(slot);if(ItemStack.isSameItemSameComponents(stack,variant))total+=stack.getCount();}return total;}
