    private static final BlockPos TRACK_SOURCE=new BlockPos(4,6,4);
    private static void trackLineFixture(GameTestHelper h,BlockPos source){
        for(int i=0;i<=7;i++){empty(h,source.east(i),source.east(20-i));h.getLevel().setBlockAndUpdate(source.east(i).below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(source.east(20-i).below(),Blocks.STONE.defaultBlockState());}
        var state=AllBlocks.TRACK.defaultBlockState().setValue(com.simibubi.create.content.trains.track.TrackBlock.SHAPE,com.simibubi.create.content.trains.track.TrackShape.XO);h.getLevel().setBlockAndUpdate(source,state);h.getLevel().setBlockAndUpdate(source.east(7),state);
    }
    private static InteractionResult actualTrackUse(GameTestHelper h,ServerPlayer player,BlockPos source,float yaw){player.setPos(Vec3.atCenterOf(source).add(0,2,3));player.setYRot(yaw);player.setXRot(0);var hit=new BlockHitResult(Vec3.atBottomCenterOf(source).add(0,.125,0),Direction.UP,source,false);return player.gameMode.useItemOn(player,h.getLevel(),player.getMainHandItem(),InteractionHand.MAIN_HAND,hit);}
