    @GameTest public void nonconsumingActualItemUseCanChangeNativeWorldWithoutPublishingSymmetryOrPayment(GameTestHelper h){
        var source=h.absolutePos(P);var target=source.east(4);empty(h,source,target);try(var joined=player(h,source)){var player=joined.player();var action=new ItemStack(SymmetryWandTestFixtures.USE_PASS_AFTER_WRITE,3);var stock=configuredMaterial(Items.STONE,3,"Three unspent PASS-result originals");var expected=stock.copy();player.getInventory().setItem(0,action);player.getInventory().setItem(4,stock);player.getInventory().setItem(8,wand(Vec3.atLowerCornerOf(source.east(2)),0));h.assertTrue(actualCoreItemUse(h,player,source,Direction.UP)==InteractionResult.PASS&&h.getLevel().getBlockState(source).is(Blocks.STONE)&&h.getLevel().getBlockState(target).isAir(),"Pinned consumesAction eligibility excludes a real native callback that writes but returns PASS");h.assertTrue(action.getCount()==3&&player.getInventory().getItem(4)==stock&&ItemStack.matches(stock,expected),"No fabricated source acceptance or mirrored original withdrawal follows a nonconsuming result");}h.succeed();
    }
    @GameTest public void actualItemUseExceptionPreservesPublishedSourceAndNoMirrorThenCleansAllNativeScopes(GameTestHelper h){
        var source=h.absolutePos(P);var target=source.east(4);empty(h,source,target);try(var joined=player(h,source)){var player=joined.player();var action=new ItemStack(SymmetryWandTestFixtures.USE_THROW_AFTER_WRITE,3);var stock=configuredMaterial(Items.STONE,3,"Three original exception-path mirror stones");var expected=stock.copy();player.getInventory().setItem(0,action);player.getInventory().setItem(4,stock);player.getInventory().setItem(8,wand(Vec3.atLowerCornerOf(source.east(2)),0));var refusal=new SymmetryWandTestFixtures.Refusal("Genuine native item use throws after own publication and source debit");SymmetryWandTestFixtures.arm(player,source,refusal,4);try{boolean failed=false;try{actualCoreItemUse(h,player,source,Direction.UP);}catch(RuntimeException|Error actual){for(Throwable cause=actual;cause!=null;cause=cause.getCause())if(cause==refusal)failed=true;}h.assertTrue(failed&&action.getCount()==2&&h.getLevel().getBlockState(source).is(Blocks.STONE)&&h.getLevel().getBlockState(target).isAir()&&ItemStack.matches(stock,expected),"Actual original failure retains already-published source and exact unspent mirror materials, with no success event or snapshot rollback");player.getInventory().setItem(6,player.getInventory().removeItemNoUpdate(0));player.getInventory().setItem(0,player.getInventory().removeItemNoUpdate(4));h.getLevel().setBlockAndUpdate(source,Blocks.AIR.defaultBlockState());h.assertTrue(actualCoreItemUse(h,player,source,Direction.UP).consumesAction()&&h.getLevel().getBlockState(source).is(Blocks.STONE)&&h.getLevel().getBlockState(target).is(Blocks.STONE)&&ItemStack.matches(player.getMainHandItem(),expected.copyWithCount(1))&&player.getInventory().getItem(6)==action&&action.getCount()==2,"Fresh genuine ordinary source after Error has one live native receipt, one mirrored charge, and the previous remaining action keeps its actual owner");}finally{SymmetryWandTestFixtures.clear();}}h.succeed();
    }
