        var types=List.of(SymmetryWandTestFixtures.USE_SUCCESS_NO_WRITE,SymmetryWandTestFixtures.USE_FINAL_AIR);for(int i=0;i<types.size();i++){var source=h.absolutePos(P.south(i*5));var target=source.east(4);empty(h,source,target);try(var joined=player(h,source)){var player=joined.player();var action=new ItemStack(types.get(i),3);var stock=configuredMaterial(Items.STONE,3,"Three original no-final-state stones "+i);var expected=stock.copy();player.getInventory().setItem(0,action);player.getInventory().setItem(4,stock);player.getInventory().setItem(8,wand(Vec3.atLowerCornerOf(source.east(2)),0));h.assertTrue(actualCoreItemUse(h,player,source,Direction.UP).consumesAction()&&action.getCount()==2&&h.getLevel().getBlockState(source).isAir()&&h.getLevel().getBlockState(target).isAir()&&ItemStack.matches(stock,expected),"Real successful native action can have no accepted section or a first snapshot whose final state is AIR; neither creates a source-eligible reflected block or payment");}}h.succeed();
