    @GameTest public void nativeReturnedHandOwnerIsPublishedBeforeItsExactOriginalsCanFundMirroring(GameTestHelper h){
        var source=h.absolutePos(P);var target=source.east(4);empty(h,source,target);try(var joined=player(h,source)){var player=joined.player();var action=new ItemStack(SymmetryWandTestFixtures.USE_RESULT_TRANSFORM);var returned=configuredMaterial(Items.GOLD_BLOCK,2,"Two actual originals returned by native result");var expected=returned.copy();player.getInventory().setItem(0,action);player.getInventory().setItem(8,wand(Vec3.atLowerCornerOf(source.east(2)),0));SymmetryWandTestFixtures.returnActualUseResult(player.level(),source,returned);try{h.assertTrue(actualCoreItemUse(h,player,source,Direction.UP).consumesAction()&&h.getLevel().getBlockState(source).is(Blocks.GOLD_BLOCK)&&h.getLevel().getBlockState(target).is(Blocks.GOLD_BLOCK),"Real native Success result transforms the source hand before its newly owned original material may fund the mirror");h.assertTrue(player.getMainHandItem()==returned&&ItemStack.matches(returned,expected.copyWithCount(1))&&player.getInventory().countItem(Items.GOLD_BLOCK)==1,"The actual native returned owner pays exactly one original and retains every component; GameMode cannot later overwrite the debit with its original two-unit result");}finally{SymmetryWandTestFixtures.clear();}}h.succeed();
    }
    @GameTest(structure="create_test:reservoir") public void genuineNestedNativeItemUseBeforeOuterPublicationKeepsTwoSourceReceiptsAndThreeFiniteMaterials(GameTestHelper h){
        var source=h.absolutePos(P);var nested=source.south(4);var target=source.east(4);var nestedTarget=nested.east(4);empty(h,source,nested,target,nestedTarget);try(var joined=player(h,source)){var player=joined.player();var action=new ItemStack(SymmetryWandTestFixtures.USE_NESTED);var originals=configuredMaterial(Items.STONE,3,"Three exact originals for nested source and two mirrors");var wand=wand(Vec3.atLowerCornerOf(source.east(2)),0);player.getInventory().setItem(0,action);player.getInventory().setItem(4,originals);player.getInventory().setItem(8,wand);SymmetryWandTestFixtures.nativeItemUseFromCallback(player,source,nested,4);try{h.assertTrue(actualCoreItemUse(h,player,source,Direction.UP).consumesAction(),"Genuine outer native item actually invokes a second GameMode item use before its own first source write");for(var at:List.of(source,nested,target,nestedTarget))h.assertTrue(h.getLevel().getBlockState(at).is(Blocks.STONE),"Each independently genuine native source owns exactly its own reflected publication");h.assertTrue(action.isEmpty()&&originals.isEmpty()&&player.getInventory().getSelectedSlot()==0&&player.getInventory().countItem(Items.STONE)==0&&player.getInventory().getItem(8)==wand,"Nested native source and its mirror pay two originals; outer mirror pays the final third, with no captured mirror-as-source, lost slot owner, recursive extra charge or stale scope");}finally{SymmetryWandTestFixtures.clear();}}h.succeed();
    }
