    @GameTest(structure="create_test:reservoir") public void nativeFunnelMirrorProbeRunsExternalProtectionBeforePaymentWithoutStartingCorePlacementIntent(GameTestHelper h){
        for(int i=0;i<2;i++){boolean denied=i==1;var target=h.absolutePos(P.south(i*6));var genuine=target.east(3);empty(h,target,genuine);h.getLevel().setBlockAndUpdate(target.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(genuine.below(),Blocks.STONE.defaultBlockState());try(var joined=player(h,target)){var player=joined.player();var stock=configuredMaterial(AllBlocks.BRASS_FUNNEL.asItem(),3,"Three exact original probe funnels "+i);var expected=stock.copy();player.getInventory().setItem(0,stock);SymmetryWandTestFixtures.watchPlace(player.level(),target);if(denied)SymmetryWandTestFixtures.denyPlace(player.level(),target);try{boolean placed=SymmetryPlacement.place(player,target,AllBlocks.BRASS_FUNNEL.defaultBlockState());h.assertTrue(placed==!denied&&SymmetryWandTestFixtures.nativePlaceVisits(player.level(),target)==1,"The real external Fabric protection callback observes the exact target once; held FunnelItem cannot start its source placement intent during mirrored preflight");h.assertTrue(denied?h.getLevel().getBlockState(target).isAir():h.getLevel().getBlockState(target)==AllBlocks.BRASS_FUNNEL.defaultBlockState(),"Only authorized actual mirrored publication can own the precise funnel state");h.assertTrue(player.getMainHandItem()==stock&&ItemStack.matches(stock,expected.copyWithCount(denied?3:2)),"Denied target preserves all three exact originals; accepted target consumes exactly one at native publication without an early source-item charge");var hit=new BlockHitResult(Vec3.atCenterOf(genuine),Direction.UP,genuine,false);h.assertTrue(net.fabricmc.fabric.api.event.player.UseBlockCallback.EVENT.invoker().interact(player,player.level(),InteractionHand.MAIN_HAND,hit).consumesAction()&&h.getLevel().getBlockState(genuine).is(AllBlocks.BRASS_FUNNEL)&&player.getMainHandItem()==stock&&ItemStack.matches(stock,expected.copyWithCount(denied?2:1)),"Outside the exact probe scope, the original real core FunnelItem intent still runs and pays one genuine native source placement");}finally{SymmetryWandTestFixtures.clear();}}}h.succeed();
    }
    @GameTest public void nativeClickToLinkMirrorProbeKeepsRealSourceSelectionUntouchedAndStillRunsExternalProtection(GameTestHelper h){
        var target=h.absolutePos(P);empty(h,target);try(var joined=player(h,target)){var player=joined.player();var source=configuredMaterial(AllBlocks.DISPLAY_LINK.asItem(),3,"Three real unselected display-link owners");var expectedSource=source.copy();var stone=configuredMaterial(Items.STONE,2,"Two original authorized mirror stones");var expectedStone=stone.copy();player.getInventory().setItem(0,source);player.getInventory().setItem(4,stone);SymmetryWandTestFixtures.watchPlace(player.level(),target);try{h.assertTrue(SymmetryPlacement.place(player,target,Blocks.STONE.defaultBlockState())&&h.getLevel().getBlockState(target).is(Blocks.STONE)&&SymmetryWandTestFixtures.nativePlaceVisits(player.level(),target)==1,"Real external Fabric callback runs while the source-held ClickToLink item cannot consume preflight with a selection action");h.assertTrue(player.getMainHandItem()==source&&ItemStack.matches(source,expectedSource)&&!source.has(AllDataComponents.CLICK_TO_LINK_DATA)&&player.getInventory().getItem(4)==stone&&ItemStack.matches(stone,expectedStone.copyWithCount(1)),"The real source hand/configuration/selection remains unchanged; exactly one actual authorized material funds the mirrored block");var hit=new BlockHitResult(Vec3.atCenterOf(target),Direction.UP,target,false);h.assertTrue(net.fabricmc.fabric.api.event.player.UseBlockCallback.EVENT.invoker().interact(player,player.level(),InteractionHand.MAIN_HAND,hit).consumesAction()&&source.get(AllDataComponents.CLICK_TO_LINK_DATA)!=null&&source.get(AllDataComponents.CLICK_TO_LINK_DATA).selectedPos().equals(target)&&source.getCount()==3&&ItemStack.matches(stone,expectedStone.copyWithCount(1)),"After probe scope closes, a genuine original ClickToLink source action still selects its actual target without losing or paying another original material");}finally{SymmetryWandTestFixtures.clear();}}h.succeed();
    }
